# What to ask VirusTotal about this IOC, or why not to
ioc = inputs['ioc'] if is_dict(inputs['ioc']) else {}
ioc_type = ioc.get('ioc_type') if is_dict(ioc.get('ioc_type')) else {}
kind = str(ioc_type.get('type_name') or '').strip().lower()
value = str(ioc.get('ioc_value') or '').strip()


def component(kind, value):
    # Composite types (filename|sha256, ip-dst|port, domain|ip): keep the part VirusTotal knows
    if '|' in kind and '|' in value:
        kinds = kind.split('|')
        values = value.split('|')
        for wanted in ('sha256', 'sha1', 'md5', 'url', 'domain', 'hostname', 'ip-dst', 'ip-src'):
            if wanted in kinds and kinds.index(wanted) < len(values):
                return values[kinds.index(wanted)].strip()
    return value


def target(value):
    lowered = value.lower()
    if re_fullmatch('[0-9a-f]{32}|[0-9a-f]{40}|[0-9a-f]{64}', lowered):
        return {'collection': 'files', 'id': lowered, 'gui': 'file'}
    info = ip_info(value)
    if info:
        if not info['is_global']:
            return {'reason': 'Private or reserved address: not sent to VirusTotal'}
        return {'collection': 'ip_addresses', 'id': value, 'gui': 'ip-address'}
    if '://' in value:
        parsed = url_parse(value)
        if parsed and parsed['scheme'] in ('http', 'https') and parsed['host']:
            # URL identifiers are the unpadded URL-safe base64 of the URL
            return {'collection': 'urls', 'id': base64_encode(value, urlsafe=True, padding=False), 'gui': 'url'}
        return {'reason': 'Only http(s) URLs are looked up'}
    if re_fullmatch('([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\\.)+[a-z]{2,63}\\.?', lowered) and len(lowered) <= 253:
        return {'collection': 'domains', 'id': lowered.rstrip('.'), 'gui': 'domain'}
    return {'reason': f'IOC type {kind or "unknown"} is not looked up on VirusTotal'}


value = component(kind, value)
found = target(value) if value else {'reason': 'Empty IOC value'}
previous = ioc.get('ioc_enrichment')
previous = previous.get('virustotal') if is_dict(previous) else None
# Once a day per value: the enrichment this workflow writes fires the update event again
if is_dict(previous) and previous.get('value') == value \
        and str(previous.get('checked_at') or '')[:10] == inputs['now'][:10]:
    found = {'reason': 'Already looked up on VirusTotal today'}
result = dict(found)
result.update({'supported': 'collection' in found, 'value': value, 'kind': kind})
